interface User {
  id: number;
  name: string;
  email: string;
  isActive: boolean;
}

function createUser(data: Omit<User, "id">): User {
  return {
    id: Date.now(),
    ...data
  };
}

const user = createUser({
  name: "Alice",
  email: "alice@example.com",
  isActive: true
});
